import{z as s,x as l,o as r,c as d,q as i,j as A,D as B,d as a,s as o,S as t,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"劳动政策的因果证据","description":"","frontmatter":{"title":"劳动政策的因果证据","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ca-labor-policy-evidence.md","filePath":"econ/ca-labor-policy-evidence.md","lastUpdated":1791063341000}'),c={name:"econ/ca-labor-policy-evidence.md"};function p(C,E,D,m,u,h){const n=l("Mermaid");return r(),d("div",null,[E[2]||(E[2]=i('<h1 id="劳动政策的因果证据" tabindex="-1">劳动政策的因果证据 <a class="header-anchor" href="#劳动政策的因果证据" aria-label="Permalink to &quot;劳动政策的因果证据&quot;">​</a></h1><div class="epigraph"><p>劳动政策的证据史是一部设计史：同一条法条，对照组每换一次，结论就重排一次。</p><footer>—— 据 Card and Krueger, AER 1994；Card, Kluve and Weber, JEP 2018 整理</footer></div><p><a href="/econ/ca-education-causal">上一课</a>把教育的三个设计——校内随机、编班断点、法律工具——跑了一遍。本课搬到劳动政策：最低工资、所得税抵免、失业保险与贸易冲击。这里的处理是州与州立法写出来的，天然供给<a href="/econ/difference-in-differences">双重差分</a>的对照；缺口从「有没有变异」移到「对照够不够近、读数是谁的效应」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>教科书预测干脆利落：下限之上就业收缩、补贴之下劳动供给上升、福利之下失业拉长。数据不配合：<a href="/econ/minimum-wage-debates">最低工资两代文献</a>里就业弹性接近零，<a href="/econ/monopsony-wages">买方垄断与工资压低</a>解释了为什么。缺口不是再找一个显著系数，而是：同一条法条，用全国青少年当基线是一个结论，用相邻县当对照是另一个；州间共同趋势、空间溢出、与政策选址的相关，任何一条断掉，平行趋势就只剩假设。劳动政策的因果问题因此精确为：这次上调、对这批人、在这个劳动市场里的净效应是多少——以及它凭什么代表下一次。</p><p><span class="marginnote">平行趋势就是「假如没政策，两条线本会平行走」的假设：处理州与对照州政策前的走势一致，才敢把政策后的差读成效应。初学者容易以为「水平长得像」就够了——要的是政策前多个时期的变动方向一致，不是某一年的数值接近。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计谱系按对照的收窄方向排。两州两组是起点：1992 年 4 月新泽西把最低工资从 4.25 提到 5.05 美元，Card–Krueger 用宾州快餐店做对照。相邻县设计把对照换到同一劳动市场的另一侧，洗掉区域趋势（Dube–Lester–Reich 2010）。Cengiz–Dube–Lindner–Zipperer 2019 再进一步：收 1979–2016 年间一百多次州级上调，把「恰好落在新下限之上工资窗口里的岗位」当受影响组，按队列加权显式聚合组-时间效应——这正是<a href="/econ/pe-staggered-did-revisions">交错 DiD 的最新修正</a>落地的样子。税式支出有自己的准实验：EITC 扩张按子女数分群，单身母亲受惠、无子女者不受，分群差中差读供给反应（Eissa–Liebman 1996）；拐点聚集（Saez 2010）把报税表在抵免拐点处的密集当弹性读数。失业保险的证据落在两条边上：耗尽日前离职率的陡升，与期限对福利水平的弹性 0.5–1.0（Krueger–Meyer 2002 的综述）。贸易冲击则示范份额-移动设计：用基期就业份额乘以国家层面的进口冲击造出地区暴露（<a href="/econ/china-shock">China shock</a>）。</p>',8)),(r(),A(t,null,{default:B(()=>[o(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAW%5B%22%E6%B3%95%E6%9D%A1%EF%BC%9A%E5%A4%84%E7%90%86%E7%94%B1%E7%AB%8B%E6%B3%95%E5%AE%9A%E4%B9%89%22%5D%20--%3E%20S1%5B%22%E6%97%B6%E9%97%B4%E7%BC%9D%EF%BC%9A%E4%B8%A4%E5%B7%9E%20DiD%22%5D%0A%20%20LAW%20--%3E%20S2%5B%22%E7%A9%BA%E9%97%B4%E7%BC%9D%EF%BC%9A%E7%9B%B8%E9%82%BB%E5%8E%BF%E5%AF%B9%E7%85%A7%22%5D%0A%20%20LAW%20--%3E%20S3%5B%22%E5%B7%A5%E8%B5%84%E7%BC%9D%EF%BC%9A%E5%8F%97%E5%BD%B1%E5%93%8D%E7%AA%97%E5%8F%A3%E7%9A%84%E9%98%9F%E5%88%97%E8%81%9A%E5%90%88%22%5D%0A%20%20LAW%20--%3E%20S4%5B%22%E7%A8%8E%E8%A1%A8%E7%BC%9D%EF%BC%9AEITC%20%E5%88%86%E7%BE%A4%E4%B8%8E%E6%8B%90%E7%82%B9%E8%81%9A%E9%9B%86%22%5D%0A%20%20S1%20--%3E%20INC%5B%22%E5%BD%92%E5%AE%BF%EF%BC%9A%E5%B0%B1%E4%B8%9A%E3%80%81%E4%BB%B7%E6%A0%BC%E3%80%81%E5%B7%A5%E6%97%B6%E3%80%81%E8%BF%9B%E5%85%A5%E9%80%80%E5%87%BA%22%5D%0A%20%20S2%20--%3E%20INC%0A%20%20S3%20--%3E%20INC%0A%20%20S4%20--%3E%20INC%0A%20%20INC%20--%3E%20META%5B%22%E5%85%83%E5%88%86%E6%9E%90%EF%BC%9A%E4%B8%AD%E4%BD%8D%E8%BF%91%E9%9B%B6%E4%B8%8E%E5%8F%91%E8%A1%A8%E9%80%89%E6%8B%A9%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,[e("span",{class:"marginnote"},"Card–Krueger 的读数：1992 年 2 月到 11 月，新泽西样本店的全职等效岗位从 20.44 升到 21.03，宾州从 23.33 降到 21.17，差中差约 +2.8。效应是「没有证据表明下降」，不是「证明了上升」——置信区间宽，这句话在之后三十年里被反复读错。")],-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,[a("谱系为什么这样长：处理由法条定义，法条在时间、州界、工资分布下截、税表、领取期限上留下多条不连续的缝，每条缝是一处可剥离的变异，设计就是把哪条缝当反事实的宣言。机制的轴在归宿：最低工资的负担不只在就业，还在价格与进入退出（Harasztosi–Lindner 2019 匈牙利大上调里相当部分由涨价吸收）；EITC 抬了劳动参与，也在均衡里压低了税前工资——补贴名义给工人，雇主分走一块，这是"),e("a",{href:"/econ/tax-incidence"},"税收归宿"),a("的算术在劳动政策上的重演；法定福利若能全额落到工资上，甚至可能是近乎免费的覆盖扩张（Summers 1989）。不这么做会错在哪：只盯就业一个边际，会漏掉价格、工时与进入退出的全部再分配；只报一次上调，会把买方垄断区间里安全的小调当成普适常数。")],-1)),(r(),A(t,null,{default:B(()=>[o(n,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20MW%5B%22%E6%9C%80%E4%BD%8E%E5%B7%A5%E8%B5%84%E4%B8%8A%E8%B0%83%22%5D%20--%3E%20J%5B%22%E5%B0%B1%E4%B8%9A%E8%BE%B9%E9%99%85%3A%20%E5%B0%8F%E5%B9%85%E4%B8%8A%E8%B0%83%E5%BC%B9%E6%80%A7%E8%BF%91%E9%9B%B6%22%5D%0A%20%20MW%20--%3E%20P%5B%22%E4%BB%B7%E6%A0%BC%E8%BE%B9%E9%99%85%3A%20%E6%B6%A8%E4%BB%B7%E5%90%B8%E6%94%B6%E7%9B%B8%E5%BD%93%E9%83%A8%E5%88%86%22%5D%0A%20%20MW%20--%3E%20H%5B%22%E5%B7%A5%E6%97%B6%E4%B8%8E%E8%BF%9B%E5%85%A5%E9%80%80%E5%87%BA%22%5D%0A%20%20EITC%5B%22EITC%20%E8%A1%A5%E8%B4%B4%22%5D%20--%3E%20LP%5B%22%E5%8A%B3%E5%8A%A8%E5%8F%82%E4%B8%8E%E4%B8%8A%E5%8D%87%22%5D%0A%20%20EITC%20--%3E%20PW%5B%22%E5%9D%87%E8%A1%A1%E4%B8%AD%E7%A8%8E%E5%89%8D%E5%B7%A5%E8%B5%84%E8%A2%AB%E5%8E%8B%E4%BD%8E%22%5D%0A%20%20J%20--%3E%20INC%5B%22%E5%BD%92%E5%AE%BF%3A%20%E8%B4%9F%E6%8B%85%E7%94%B1%E8%B0%81%E5%88%86%E6%91%8A%22%5D%0A%20%20P%20--%3E%20INC%0A%20%20H%20--%3E%20INC%0A%20%20PW%20--%3E%20INC%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=i('<p><span class="marginnote">归宿可以想成在劳资之间加一块挡板：挡板挡住的负担自己会找出口。匈牙利那次大上调里，相当一部分成本被企业用涨价转给了消费者，而不是全数变成裁员；EITC 名义补贴工人，均衡里雇主也分走一块——所以只盯就业一个数字，读不到再分配的全貌。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>外推的红线<a href="/econ/minimum-wage-debates">最低工资课</a>已经划过：越线的大上调、长期弹性、空间异质。元分析的收口在 Card–Kluve–Weber 2018：中位就业效应近似零，但漏斗图左尾有选择性——显著为负的估计更容易发表；所以「文献证明没有影响」与「文献证明有影响」都不对，文献证明的是设计质量决定读数。证据还随宏观位置移动：紧缩期与扩张期的同幅上调，就业后果不同。读完本课的默认口径：劳动政策的任何数字先问三个坐标——处理的法条维度、对照的构造、归宿落在哪个边际。</p><p><span class="marginnote">常见误区：把元分析读成「文献证明了没有影响」。实际的中位读数近似零，但漏斗图左尾有选择性——显著为负的估计更容易发表。文献真正证明的是设计质量决定结论：买方垄断区间里安全的小幅上调，与越线的大上调，从来不是同一个实验。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>劳动政策天然多缝：州法、工资下截、税表拐点、领取期限，每条缝对应一个设计。</li><li>对照地理与队列越近，平行趋势越可信：两州 → 相邻县 → 队列聚合。</li><li>归宿是机制的轴：就业、价格、工时与进入退出一起动，补贴的负担会被均衡分摊。</li><li>元分析给出中位近零但有发表选择；证据的边界是设计，不是口号。</li><li>出处：Card and Krueger, AER 1994；Dube–Lester–Reich, REStat 2010；Cengiz 等, QJE 2019；Eissa and Liebman, QJE 1996；Saez, AEJ: Policy 2010；Krueger and Meyer, JEP 2002；Card, Kluve and Weber, JEP 2018。</li></ul>',6))])}const T=s(c,[["render",p]]);export{b as __pageData,T as default};
